// Normalize the six production-sheet fields for the frontend.
// Do not expose spreadsheet row metadata or untrusted link targets.
const rows = $input.all().map(item => item.json || {});
const reports = rows.filter(row => {
  const branch = String(row.branch ?? '').trim();
  const month = String(row.report_month ?? '').trim();
  const filename = String(row.file_name ?? '').trim();
  const id = String(row.drive_file_id ?? '').trim();
  return Boolean(branch) && /^\d{4}-(0[1-9]|1[0-2])$/.test(month) && /\.pdf$/i.test(filename) && /^[A-Za-z0-9_-]{10,128}$/.test(id);
}).map(row => {
  const driveId = String(row.drive_file_id).trim();
  return {
    branch: String(row.branch).trim(),
    report_month: String(row.report_month).trim(),
    file_name: String(row.file_name).trim(),
    uploaded_at: String(row.uploaded_at ?? '').trim(),
    drive_file_id: driveId,
    file_link: `https://drive.google.com/file/d/${driveId}/view`
  };
});
reports.sort((a, b) => b.report_month.localeCompare(a.report_month) || b.uploaded_at.localeCompare(a.uploaded_at));
const branches = [...new Set(reports.map(r => r.branch))].sort((a, b) => a.localeCompare(b));
return [{json: {
  success: true,
  total: reports.length,
  branches,
  latest_report_month: reports[0]?.report_month ?? null,
  reports,
  fetched_at: new Date().toISOString()
}}];

